"""Build only this static design artifact; no product implementation or publication."""
from pathlib import Path
from html import escape
ROOT = Path(__file__).resolve().parent

def diagram(stem, description):
    svg = ROOT / (stem + '.svg')
    if svg.exists():
        return '<div class="diagram">' + svg.read_text() + '</div>'
    return '<div class="pending" role="note"><strong>DIAGRAM PENDING LOCAL RENDER</strong><p>' + escape(description) + '</p><p>本机 Chromium 启动被权限限制阻止；标准参数重试仍失败。图源随设计保存，尚无已渲染图。下方文字说明保留完整含义。</p></div>'

sections = [
('summary','01 / 一句话结论', '<p class="hero">把<strong>等你处理的事</strong>放在最上面，每一条都说清<strong>是什么、做什么、等多久、去哪里</strong>。</p><p>大任务下面的活和独立散活都能进入这份清单。三路都查完、确实为空时，直接告诉你「现在没有等你的事」。这是设计交付，功能实现与实际点击验证由后续阶段完成。</p>'),
('flow','02 / 改了什么：三路汇到同一处', diagram('d1-flow','三路汇合：确认门、未答问题、点名返回的单；同单合并，再生成四段与讨论串入口。') + '<p><b>确认门</b>是需要一次确认才能继续的关口。<b>Lead</b>是负责推进工作的组长。未答问题可能仍在等组长回复，页面不会伪造“已经升级给你”的记录；每条问题会补写正在等哪个角色回复。</p><p>同一单同时出现在三路，只显示一行；每个来源保留下来。需要上线确认的动作先说，然后是普通确认、回答问题、点名回来查看。其它动作仍在第二段，独立问题不会被合并丢掉。</p>'),
('sample','03 / 你会看到的四段', '<p class="small">文案示例；不是生产数据，也不是已经验证的链接。</p><dl><dt>① 这是什么</dt><dd>在等你按一下 · FLY-2483 · 现在要你看</dd><dt>② 需要你做什么</dt><dd>去 thread 里回一句「同意」或「打回」。thread 就是这张单专属的讨论串。</dd><dt>③ 等了多久</dt><dd>自 10:00 起,已等 2 小时（示例日期 2026-09-09，UTC；UTC 是统一对时的时间标准）。</dd><dt>④ 去哪儿做</dt><dd><span aria-disabled="true">不知道（设计示例没有绑定真实讨论串）</span></dd></dl><p>任何一段拿不到，都把「不知道」写在原位。不会删除整段，也不会拿其它网站的链接冒充讨论串。</p>'),
('words','04 / 类型与动作固定配对', '<dl><dt>在等你按一下</dt><dd>去 thread 里回一句「同意」或「打回」。</dd><dt>体在问你一句话</dt><dd>去 thread 里回答它的问题。</dd><dt>ship 卡在你手里</dt><dd>ship 是上线交付前的确认环节。去 thread 里点 :cool: 或说停。</dd><dt>你点过名要回来找你</dt><dd>去看一眼,决定继续还是停。</dd></dl><p>以后遇到不认识的类型，保留原始类型，动作写「不确定,去看一眼」。这些文案只带你回讨论串，不增加任何批准权限。</p>'),
('model','05 / 数据怎么留出处', diagram('d2-model','每张页面有一份服务器配置；每个等待事项保留多个原始来源和本单讨论串绑定。') + '<p><b>Cell</b>是一个带出处的小格子：值是什么、什么时候看到、来自哪里；没有值就写缺什么。<b>attention[]</b>是这些等待事项组成的清单。</p><p>Discord 是承载讨论串的聊天应用。它的服务器编号只持久保存一份，来自配置；讨论串编号来自单子的正式绑定。两个编号都齐才生成链接。配置移除或编号无效，下一次生成就灰掉，不能借旧值继续拼。</p>'),
('truth','06 / 不知道的地方要说出来', '<p>标签是什么时候加上的，目前没有可信记录，所以只靠点名标签进入的单会写「等了多久：不知道」。单子创建时间不能冒充开始等待的时间。</p><p>只要有一路没查完、身份没核齐，或清单超出页面体积，就写「已知 N 条记录，清单不完整」。超限保留完整行并明示未显示全部事项；身份恢复后，同一件事再合并。没有大任务或日常筐时仍显示等你的事，同时解释大任务范围不可用；调度系统也得到不可用，命令行查看依赖会明确提示补齐大任务前置，不能当成没有工作。</p><p>问题记录即使超过十四天、原工作会话已经结束，只要没有正式答复或关闭，仍然保留。身份不明的未答问题也不悄悄消失。</p>'),
('tradeoffs','07 / 为什么这样做', '<p><b>选择：先收集项目内事实，再生成页面。</b>同一份数据同时服务页面和出处核对，散活不依赖先挂进大任务。</p><p><b>放弃：从旧的大任务卡临时凑清单。</b>它只知道范围内的单，还会丢掉久未答的问题。</p><p><b>放弃：让组长手写清单或让浏览器现查聊天服务。</b>前者会旧，后者需要额外权限和凭据。现在这条路的代价是标签更新最多滞后一个巡检周期，页面继续显示更新时间。</p>'),
('qa','08 / 怎么证明真的能用', '<p><b>QA</b>是独立验证阶段。先造三条可核对的数据：一个确认门、一个独立散活的问题、一个点名返回的单。首屏必须恰好三行，每行四段齐全；另造“体说卡住了”不能多出第四条。</p><p><strong>随后必须真的点击。</strong>用 Claude-in-Chrome（浏览器操作工具）从生成页点开链接，核对地址、单号和讨论串标题，截图放进验收报告。登录页、首页、父频道或错误讨论串都不算通过。</p><p>还要在隔离环境去掉服务器编号，截图证明入口灰掉且原因可读。当前设计阶段没有这条真实点击截图，不能写成已验证。</p>'),
('boundary','09 / 已知边界与当前证据', '<p>这次新增首屏等待区与它的取数、存储和校验；原来的大任务、子单渲染保持原样。没有新增排期页、排序判断、页面直接批准或自动留言回传。</p><p>文案使用角色称呼，不写死人名。来自任务系统的真实标题保留并转义；转义是把特殊字符当文字显示，避免它们变成页面代码。</p><p>当前只完成设计文档与评论脚本检查。两张图因本机浏览器权限限制保留待渲染标识；没有产品实现测试、真实讨论串点击或生产上线结果。</p>'),
('rollback','10 / 风险与回退', '<p>链接格式正确不等于访问权限正确，真实点击仍是必须通过的一关。各来源不是同时读取，页面显示观察时间；真正的确认继续交给原讨论串的规则。</p><p>配置删除后，新页面会禁用链接；已经发布的旧页面不会瞬间变化。回退代码会使新等待区消失，新增配置表和历史出处记录保留。</p><p>合并与部署分开：上线仍由独立更新服务在原窗口进行。本设计节点不执行合并、部署或后继派发。</p>')]

def comment(key,title):
    return '<div class="comment"><label for="comment-' + escape(key) + '">这一节的意见<span data-saved="' + escape(key) + '" aria-live="polite"></span></label><textarea id="comment-' + escape(key) + '" data-comment="' + escape(key) + '" data-title="' + escape(title) + '" placeholder="写下你希望调整的地方"></textarea></div>'

cards = ['<section class="card" id="' + escape(key) + '"><h2>' + escape(title) + '</h2>' + body + comment(key,title) + '</section>' for key,title,body in sections]
cards.append('<section class="card" id="comments"><h2>11 / 页面意见汇总</h2><p>留言只存于本机。复制后贴回讨论串，才会被组长收到。汇总标记表示修改意见，不表示通过。</p>' + comment('comments','11 / 页面意见汇总') + '<button type="button" id="copy-all">复制全部意见</button><span id="copy-status" aria-live="polite"></span><div id="comment-chunks"></div></section>')

SCRIPT = '\n(() => {\n  \'use strict\';\n  const marker = \'【页面意见汇总】FLY-2483\';\n  const prefix = \'flywheel:design-comments:\' + location.pathname + \':\';\n  const inputs = Array.from(document.querySelectorAll(\'textarea[data-comment]\'));\n  const chunksBox = document.getElementById(\'comment-chunks\');\n  const status = document.getElementById(\'copy-status\');\n  let chunks = [];\n  function splitText(text) {\n    const chars = Array.from(text);\n    const room = 1800 - Array.from(marker).length - 1;\n    if (!chars.length) return [marker + \'\\n（暂无意见）\'];\n    const result = [];\n    let part = \'\';\n    for (const char of chars) {\n      if (part.length + char.length > room) {\n        result.push(marker + \'\\n\' + part);\n        part = \'\';\n      }\n      part += char;\n    }\n    if (part) result.push(marker + \'\\n\' + part);\n    return result;\n  }\n  function fallbackCopy(text) {\n    const helper = document.createElement(\'textarea\');\n    helper.value = text;\n    helper.setAttribute(\'aria-label\', \'复制意见\');\n    helper.style.position = \'fixed\';\n    helper.style.left = \'-10000px\';\n    document.body.appendChild(helper);\n    helper.select();\n    let ok = false;\n    try { ok = document.execCommand(\'copy\'); } catch (_) { ok = false; }\n    helper.remove();\n    return ok;\n  }\n  async function copyText(text) {\n    let ok = false;\n    if (navigator.clipboard && typeof navigator.clipboard.writeText === \'function\') {\n      try { await navigator.clipboard.writeText(text); ok = true; }\n      catch (_) { ok = fallbackCopy(text); }\n    } else { ok = fallbackCopy(text); }\n    status.textContent = ok ? \'已复制\' : \'复制失败，请选中下方文字手动复制\';\n  }\n  function updateSummary() {\n    const entries = inputs.filter(input => input.value.trim()).map(input =>\n      input.dataset.title + \'\\n\' + input.value.trim());\n    chunks = splitText(entries.join(\'\\n\\n\'));\n    chunksBox.replaceChildren();\n    chunks.forEach((chunk, index) => {\n      const block = document.createElement(\'div\');\n      block.className = \'chunk\';\n      const text = document.createElement(\'pre\');\n      text.textContent = chunk;\n      const button = document.createElement(\'button\');\n      button.type = \'button\';\n      button.className = \'secondary\';\n      button.textContent = \'复制第 \' + (index + 1) + \' 段\';\n      button.addEventListener(\'click\', () => copyText(chunk));\n      block.appendChild(text);\n      block.appendChild(button);\n      chunksBox.appendChild(block);\n    });\n  }\n  inputs.forEach(input => {\n    const saved = document.querySelector(\'[data-saved="\' + input.dataset.comment + \'"]\');\n    try { input.value = localStorage.getItem(prefix + input.dataset.comment) || \'\'; }\n    catch (_) { if (saved) saved.textContent = \'无法读取本机保存\'; }\n    input.addEventListener(\'input\', () => {\n      try {\n        localStorage.setItem(prefix + input.dataset.comment, input.value);\n        if (saved) saved.textContent = \'已保存\';\n      } catch (_) { if (saved) saved.textContent = \'未保存；仍可复制\'; }\n      updateSummary();\n    });\n  });\n  document.getElementById(\'copy-all\').addEventListener(\'click\', () => copyText(chunks.join(\'\\n\\n\')));\n  updateSummary();\n})();\n'
CSS = '\n:root{color-scheme:light;--ink:#1d1d1f;--muted:#6e6e73;--blue:#007aff}\n*{box-sizing:border-box}body{margin:0;background:#f5f5f7;color:var(--ink);font-family:-apple-system,BlinkMacSystemFont,"PingFang SC",system-ui,sans-serif;line-height:1.75}\nmain{max-width:960px;margin:auto;padding:40px 22px 80px}header{padding:10px 6px 30px}h1{font-size:clamp(28px,5vw,42px);line-height:1.25;letter-spacing:-.04em;margin:8px 0 12px}h2{font-size:21px;letter-spacing:-.015em;margin:0 0 20px}.eyebrow{font-size:12px;letter-spacing:.15em;color:var(--blue);font-weight:650}.muted,.small{color:var(--muted);font-size:13px}.card{background:#fff;border:1px solid #e8e8ed;border-radius:16px;padding:28px;margin-bottom:20px}.hero{font-size:24px;line-height:1.65;margin-top:0}p{margin:12px 0}.tag{display:inline-block;padding:5px 10px;background:#edf5ff;color:#145b9b;border-radius:6px;font-size:12px;margin:8px 8px 0 0}.diagram{overflow-x:auto}.diagram svg{display:block;max-width:100%;height:auto;margin:8px auto 24px}.pending{padding:20px;border:1px dashed #c58c33;border-radius:8px;background:#fffaf0;color:#725320;font-size:14px;margin:12px 0 22px}.pending strong{font-size:12px;letter-spacing:.06em}.pending p{margin:6px 0}dl{margin:18px 0}dt{font-weight:650;color:#15599c;margin-top:18px}dd{margin:5px 0 0}.sample{background:#f5f5f7;padding:18px;border-radius:8px}code{font:13px "SFMono-Regular",Consolas,monospace;background:#f5f5f7;padding:3px 6px;border-radius:4px}li{margin:7px 0}.comment{border-top:1px solid #ececf0;margin-top:24px;padding-top:18px}label{display:block;font-size:13px;color:var(--muted);margin-bottom:8px}label span{margin-left:12px;color:#237343}textarea{width:100%;min-height:76px;resize:vertical;border:1px solid #d2d2d7;border-radius:8px;padding:12px;font:inherit;font-size:14px;background:#fcfcfd}textarea:focus{outline:2px solid #7ab7ff;outline-offset:2px}button{background:var(--blue);color:#fff;border:0;border-radius:7px;padding:10px 16px;font:inherit;font-size:14px;cursor:pointer;margin:14px 12px 0 0}.secondary{background:#eaf3ff;color:#15599c}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:14px/1.7 system-ui,sans-serif;background:#f5f5f7;padding:16px;border-radius:8px}.chunk{margin-top:18px}#copy-status{font-size:13px;color:var(--muted)}a{color:#0067d6;text-decoration:none}@media(max-width:600px){main{padding:22px 12px 50px}.card{padding:22px 18px;border-radius:12px}.hero{font-size:21px}h2{font-size:18px}}\n'

html = '<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>FLY-2483 · 现在要你看</title><style>' + CSS + '</style></head><body><main><header><div class="eyebrow">FLY-2483 · 设计说明</div><h1>现在要你看。</h1><p class="muted">三路汇合 · 四段固定 · 回到正确讨论串<br>2026-09-09 · 每节下方可以直接留意见</p></header>' + ''.join(cards) + '<script nonce="__CSP_NONCE__">' + SCRIPT + '</script></main></body></html>'
(ROOT / 'founder-design.html').write_text(html)
print('Built founder-design.html:',len(html.encode()),'bytes; sections:',len(cards))
